function microContext(){return {state,saved,esc,ico,btn,bar,courseData,courseForLesson,placementFor,allCourseLessons,save,setPage,render,toast,buildTest,document};}
function tipsEntry(){return '<section class="tips-entry"><h3>Trucchi del turno: lavora con più metodo</h3><p>76 consigli operativi per Sala, Cucina e Bar: preparazione, gestione del pienone, comunicazione, riduzione degli errori e chiusura. Da consultare quando serve, senza un altro corso obbligatorio.</p>'+'<button type="button" class="btn outline" data-page="turnTips">Esplora i consigli '+ico('arrow')+'</button>'+'</section>';}
function microDashboard(id){const c=courseData(id),next=MICRO.recommendation(microContext(),id),due=MICRO.dueReviews(microContext()).length,stats=MICRO.courseMetrics(microContext(),c);return '<section class="micro-dashboard" aria-label="Microlezioni e ripassi"><h3>Una competenza alla volta.</h3><p>'+stats.completed+'/'+stats.total+' attività svolte in '+esc(c.title)+'. Riprendi dal passaggio esatto, senza dover rileggere tutto il capitolo.</p><div class="micro-dashboard-actions">'+btn('Continua lo studio '+ico('arrow'),'microContinue','data-id="'+esc(id)+'"','')+btn('Vedi i capitoli','microChapter','data-id="'+esc(id)+'"','outline')+btn('Ripassi'+(due?' ('+due+')':''),'microReviews','','ghost')+'</div></section>';}
function courseData(id){return id==="sala"?{id:"sala",title:"Fondamenti di sala",modules:M,lessons:L,questions:DATA.questions,final_questions:DATA.final_questions,skill_questions:DATA.questions,level:"fondamenta"}:ALL_COURSES[id]||null}
function placementFor(id){const c=courseData(id),p=saved.placements?.[id];return c&&PLACEMENT.valid(p,id,c)?p:null}
function recommendedLessonId(id){const c=courseData(id),p=placementFor(id);return c&&p?PLACEMENT.next(p,c,saved.done||[]):null}
function planTitle(p){return p.level==="applicazione"?"Vai direttamente alla pratica":p.level==="mirato"?"Studia solo ciò che ti serve":"Costruiamo le basi giuste"}
function placementModuleTag(moduleId){
 const m=placementFor(state.activeCourse)?.modules.find(m=>m.id===moduleId);
 return m?'<span class="lp-mini-badge" data-status="'+esc(m.status)+'">'+esc(PLACEMENT.statusLabel(m.status))+' · '+m.percent+'%</span>':"";
}
function placementPanel(id,compact=false){
 const c=courseData(id);if(!c)return "";
 const p=placementFor(id),dataId='data-id="'+esc(id)+'"';
 if(!p)return '<section class="lp-card lp-empty'+(compact?" lp-small":"")+'" aria-label="Percorso personalizzato">'
 +'<div class="lp-label">ACADEMY / PERCORSO PERSONALIZZATO</div><h2>Non devi ricominciare da zero.</h2>'
 +'<p class="lp-summary">'+(c.level==='intermedio'?'Il corso intermedio richiede decisioni operative più complesse, non conoscenze elementari. Puoi iniziare dalle lezioni o usare lo Skill Check per individuare i moduli da approfondire.':'Hai già esperienza in '+esc(c.title.toLowerCase())+'? Lo Skill Check ti aiuta a saltare le spiegazioni che conosci e a concentrarti su ciò che serve davvero.')+'</p>'
 +'<div class="lp-actions">'+btn('Trova il mio punto di partenza '+ico('arrow'),'testIntro','','')+btn('Esplora il programma','openCourse',dataId,'outline')+'</div>'
 +'<p class="lp-footnote">Lo Skill Check del corso valuta '+(c.level==='intermedio'?'situazioni intermedie':'i fondamentali')+'. Il risultato resta sul dispositivo e non è una qualifica.</p></section>';
 const next=recommendedLessonId(id),finished=p.enabled&&p.level!=="applicazione"&&!next;
 const title=planTitle(p);
 const actionText=p.enabled?(p.level==="applicazione"?(c.level==="intermedio"?"Passa alla verifica finale intermedia":"Prosegui con il corso intermedio"):next?"Inizia dalla lezione consigliata":finished?"Apri le verifiche dei moduli":"Apri il programma"):"Vai al programma completo";
 const status='<span class="lp-disabled">'+(p.enabled?"Guida attiva":"Modalità libera")+'</span>';
 const counters='<div class="lp-counts"><div class="lp-count"><strong>'+p.masteredCount+'/4</strong><span>Moduli con esito adeguato</span></div><div class="lp-count"><strong>'+p.percent+'%</strong><span>Skill Check iniziale</span></div><div class="lp-count"><strong>'+p.lessonIds.length+'</strong><span>Lezioni mirate proposte</span></div></div>';
 const modules=compact?"":'<div class="lp-modules">'+p.modules.map(m=>'<div class="lp-module" data-status="'+esc(m.status)+'"><div class="lp-module-top"><strong>'+esc(m.title)+'</strong><span class="lp-number">'+m.percent+'%</span></div><small>'+esc(PLACEMENT.statusLabel(m.status))+(m.criticalErrors?' · '+m.criticalErrors+' '+(m.criticalErrors===1?'errore critico':'errori critici'):'')+'</small></div>').join('')+'</div>';
 const critical=p.criticalErrors?'<p class="lp-disabled">'+ico('alert',15)+' '+p.criticalErrors+' '+(p.criticalErrors===1?'risposta critica richiede':'risposte critiche richiedono')+' ripasso anche con una media alta.</p>':"";
 const finishedNote=finished?'<p class="lp-disabled">Hai già segnato come studiate le lezioni suggerite. Puoi affrontare le verifiche o rifare lo Skill Check per aggiornare le indicazioni.</p>':"";
 const actions='<div class="lp-actions">'+btn(actionText+' '+ico('arrow'),'openRecommended',dataId,'')+btn(p.enabled?'Passa alla modalità libera':'Riattiva il percorso guidato','toggleLearningPlan',dataId,'outline')+btn('Rifai lo Skill Check','testIntro','','ghost')+'</div>';
 return '<section class="lp-card'+(compact?' lp-small':'')+'" aria-label="Percorso suggerito">'
 +'<div class="lp-heading"><div><div class="lp-label">IL TUO PERCORSO · '+esc(c.title)+'</div><h2>'+esc(title)+'</h2></div>'+status+'</div>'
 +'<p class="lp-summary">'+esc(p.summary)+'</p>'+counters+modules+critical+finishedNote+actions
 +'<p class="lp-footnote">Diagnosi orientativa da '+p.total+' risposte '+(c.level==='intermedio'?'su casi intermedi':'sui fondamentali')+', non certificazione. Nessuna lezione viene marcata come completata automaticamente. Il programma completo rimane sempre accessibile.'
 +(p.accessibleMode?' Modalità testuale alternativa: equivalenza con le prove visive non ancora validata.':'')+'</p></section>';
}

function nextLesson(){return L.find(x=>!saved.done.includes(x.id))||L[L.length-1]}
function studioRoleTabs(action,active){
 const names={sala:"Sala",cucina:"Cucina",bar:"Bar"};
 return '<div class="hub-role-tabs" role="group" aria-label="Scegli reparto">'+Object.entries(names).map(([id,title])=>'<button type="button" data-action="'+action+'" data-id="'+id+'" aria-pressed="'+(active===id)+'" class="'+(active===id?'selected':'')+'">'+title+'</button>').join('')+'</div>';
}
function studioCounts(){
 const ctx=microContext(),ids=["sala","cucina","bar","sala-intermedio","cucina-intermedio","bar-intermedio"];
 return {activities:ids.reduce((n,id)=>n+MICRO.courseMetrics(ctx,courseData(id)).completed,0),simulations:Object.keys(SHIFT.validResults(saved.shiftSimResults)).length,reviews:MICRO.dueReviews(ctx).length,assessments:saved.assessments.length};
}
function homeDashboard(){
 const courseId=courseData(state.activeCourse)?state.activeCourse:"sala",course=courseData(courseId),ctx=microContext();
 const m=MICRO.courseMetrics(ctx,course),counts=studioCounts(),next=MICRO.recommendation(ctx,courseId);
 const nextLesson=next?.lessonId?course.lessons.find(x=>x.id===next.lessonId):null;
 const nextText=next?.kind==="final"?"Verifica finale pronta":next?.kind==="course"&&next.courseId!==courseId?"Prosegui al livello intermedio":nextLesson?.title||"Continua il tuo programma";
 return '<div class="studio-page studio-home"><header class="studio-page-head"><div><span class="studio-eyebrow">DASHBOARD PERSONALE</span><h1>La tua attività</h1><p>Un punto di partenza chiaro, senza dover cercare tra tutte le sezioni.</p></div><span class="studio-context">'+ico('academy',16)+' '+esc(course.title)+'</span></header>'
  +draftBanner()
  +'<section class="studio-stats" aria-label="Riepilogo attività"><div class="studio-stat">'+ico('book',19)+'<strong>'+counts.activities+'<small> / 360</small></strong><span>Microattività svolte</span></div><div class="studio-stat">'+ico('target',19)+'<strong>'+counts.assessments+'</strong><span>Verifiche registrate</span></div><div class="studio-stat">'+ico('play',19)+'<strong>'+counts.simulations+'<small> / 18</small></strong><span>Simulazioni concluse</span></div></section>'
  +'<div class="studio-home-grid"><section class="studio-primary" aria-labelledby="studioContinueTitle"><span class="studio-eyebrow">IN CORSO · '+esc(courseId.includes('intermedio')?'INTERMEDIO':'FONDAMENTI')+'</span><h2 id="studioContinueTitle">'+esc(course.title)+'</h2><p class="studio-next-name">'+esc(nextText)+'</p><div class="studio-meter-head"><span>'+m.completed+' di '+m.total+' attività</span><strong>'+m.percent+'%</strong></div><div class="studio-track" role="progressbar" aria-label="Progresso del corso corrente" aria-valuemin="0" aria-valuemax="100" aria-valuenow="'+m.percent+'"><span style="width:'+m.percent+'%"></span></div><div class="studio-actions"><button class="btn studio-action" data-action="microContinue" data-id="'+esc(courseId)+'">Riprendi attività '+ico('arrow',17)+'</button><button class="btn outline" data-action="openCourse" data-id="'+esc(courseId)+'">Apri il programma</button></div></section>'
  +'<aside class="studio-home-side"><section class="studio-panel"><span class="studio-eyebrow">PRIORITÀ</span><h3>Il prossimo ripasso</h3><p>'+(counts.reviews?'Hai '+counts.reviews+' ripassi disponibili. Puoi riprendere dal punto necessario.':'Nessun ripasso in scadenza adesso. Continua il percorso per consolidare nuove attività.')+'</p><button class="studio-text-action" data-action="microReviews">Vai ai ripassi '+ico('arrow',15)+'</button></section><section class="studio-panel"><span class="studio-eyebrow">ACCESSO RAPIDO</span><div class="studio-shortcuts"><button data-page="academy">'+ico('academy')+' Academy '+ico('chev',15)+'</button><button data-page="shiftSimList">'+ico('play')+' Simulazioni '+ico('chev',15)+'</button><button data-page="progress">'+ico('medal')+' Progressi '+ico('chev',15)+'</button></div></section></aside></div>'
  +'<section class="studio-footer-links" aria-label="Altri spazi DopoTurno"><div><span class="studio-eyebrow">OLTRE LA FORMAZIONE</span><h2>Il mestiere, fuori dalle lezioni.</h2></div><div class="studio-footer-actions"><button data-page="community">'+ico('users',17)+' Community</button><button data-page="confronti">'+ico('message',17)+' Confronti</button><button data-page="career">'+ico('career',17)+' Carriera</button></div></section>'
  +'<p class="studio-privacy">Dati e risultati rimangono in questo browser. I punteggi sono formativi, non certificazioni professionali.</p></div>';
}
function academy(){
 const role=["sala","cucina","bar"].includes(state.activeCourse.split("-")[0])?state.activeCourse.split("-")[0]:"sala";
 const cid=state.activeCourse===role||state.activeCourse===role+"-intermedio"?state.activeCourse:role;
 const c=courseData(cid),ctx=microContext(),metrics=MICRO.courseMetrics(ctx,c),plan=placementFor(cid),counts=studioCounts();
 const choice=id=>{
  const cc=courseData(id),m=MICRO.courseMetrics(ctx,cc),selected=cid===id;
  return '<article class="hub-course-card'+(selected?' selected':'')+'"><div class="studio-choice-top"><div><span class="studio-eyebrow">'+(id.includes('-intermedio')?'INTERMEDIO':'FONDAMENTI')+'</span><h3>'+esc(cc.title)+'</h3></div><strong>'+m.percent+'%</strong></div><p>'+m.completedLessons+'/12 capitoli studiati</p><div class="studio-track" role="progressbar" aria-valuenow="'+m.percent+'" aria-valuemin="0" aria-valuemax="100" aria-label="Avanzamento '+esc(cc.title)+'"><span style="width:'+m.percent+'%"></span></div><button type="button" data-action="academyLevel" data-id="'+esc(id)+'" aria-pressed="'+selected+'" class="studio-level-select">'+(selected?'Percorso selezionato':'Seleziona questo livello')+' '+ico(selected?'check':'arrow',15)+'</button></article>';
 };
 const modules=c.modules.map((mod,i)=>{
  const lessons=c.lessons.filter(l=>l.module===mod.id),done=lessons.reduce((n,l)=>n+MICRO.doneKeys(saved,l.id).length,0),read=lessons.filter(l=>saved.done.includes(l.id)).length;
  const status=done===15?"COMPLETATO":done>0?"IN CORSO":"DA INIZIARE";
  return '<button type="button" class="studio-module" data-action="studioOpenModule" data-id="'+esc(mod.id)+'" data-course="'+esc(cid)+'" aria-label="Apri il modulo '+(i+1)+': '+esc(mod.title)+'"><span class="studio-module-index">'+String(i+1).padStart(2,'0')+'</span><span class="studio-module-main"><strong>'+esc(mod.title)+'</strong><small>'+status+' · '+read+'/3 capitoli · '+done+'/15 attività</small><span class="studio-mini-track"><span style="width:'+(done/15*100)+'%"></span></span></span><span class="studio-module-arrow">'+ico('arrow',17)+'</span></button>';
 }).join('');
 return '<div class="studio-page academy-hub studio-academy"><header class="studio-page-head"><div><span class="studio-eyebrow">DOPOTURNO / ACADEMY</span><h1>Il tuo percorso di studio</h1><p>Scegli reparto e livello. Il programma rimane ordinato e ogni attività è raggiungibile in pochi passaggi.</p></div>'+studioRoleTabs('academyRole',role)+'</header>'+draftBanner()
  +'<nav class="studio-local-nav" aria-label="Strumenti formativi"><button aria-current="page" data-page="academy">Percorso</button><button data-page="testIntro">Skill Check</button><button data-action="microReviews">Ripassi'+(counts.reviews?' · '+counts.reviews:'')+'</button><button data-page="shiftSimList">Simulazioni</button></nav>'
  +'<section class="studio-section" aria-labelledby="studioLevelsTitle"><div class="studio-section-header"><div><span class="studio-eyebrow">01 / IL LIVELLO</span><h2 id="studioLevelsTitle">Scegli il percorso</h2></div><p>Puoi partire dall'+"'"+'intermedio senza rifare le basi. Lo Skill Check può suggerire il punto più adatto.</p></div><div class="hub-courses studio-levels">'+choice(role)+choice(role+"-intermedio")+'</div></section>'
  +'<div class="studio-academy-grid"><section class="studio-panel studio-program" aria-labelledby="studioProgramTitle"><div class="studio-program-top"><div><span class="studio-eyebrow">02 / IL PROGRAMMA</span><h2 id="studioProgramTitle">Moduli di '+esc(c.title)+'</h2><p>Quattro moduli, tre capitoli ciascuno. Una competenza alla volta: apri quello che ti serve.</p></div><div class="studio-program-score"><strong>'+metrics.percent+'%</strong><small>'+metrics.completed+'/60 attività</small></div></div><div class="studio-module-list">'+modules+'</div><div class="studio-actions"><button type="button" class="btn studio-action" data-action="microContinue" data-id="'+esc(cid)+'">Continua il percorso '+ico('arrow',17)+'</button><button type="button" class="btn outline" data-action="openCourse" data-id="'+esc(cid)+'">Vedi tutti i capitoli</button></div></section>'
  +'<aside class="studio-academy-aside"><section class="studio-panel studio-assessment"><span class="studio-eyebrow">03 / VALUTAZIONE</span><h3>Skill Check</h3><p>'+(plan?'Percorso orientativo disponibile: puoi seguire i moduli consigliati o studiare liberamente.':'Hai già esperienza? Il test diagnostico identifica il punto da cui partire, senza suggerimenti durante la prova.')+'</p><button class="studio-text-action" data-page="testIntro">Apri lo Skill Check '+ico('arrow',15)+'</button></section><section class="studio-panel"><span class="studio-eyebrow">ALLENAMENTO</span><h3>Ripassi e simulazioni</h3><p>Ripassa le procedure e prova a prendere decisioni in 18 scenari professionali.</p><div class="studio-shortcuts"><button data-action="microReviews">'+ico('clock',18)+' Ripassi '+ico('chev',15)+'</button><button data-page="shiftSimList">'+ico('play',18)+' Scenari realistici '+ico('chev',15)+'</button></div></section><section class="studio-panel studio-compact-tools"><span class="studio-eyebrow">IN SERVIZIO</span><div class="studio-shortcuts"><button data-page="turnTips">'+ico('clock',18)+' Trucchi del turno '+ico('chev',15)+'</button><button data-page="codex">'+ico('book',18)+' Codex e riferimenti '+ico('chev',15)+'</button></div></section></aside></div>'
  +'<p class="studio-privacy">I progressi rimangono nel browser finché non esporti un backup dal Profilo. Nessuna qualifica è assegnata automaticamente.</p></div>';
}

function extraCourse(){const c=currentCourse(),n=courseProgress(c.id),completed=c.lessons.filter(l=>saved.done.includes(l.id)).length;return `<div class="breadcrumb"><button data-page="academy">Academy</button>${ico('chev')}<span>${esc(c.title)}</span></div><div class="hero-main sub-hero"><img class="hero-photo" src="${photo(c.hero)}" alt="Fotografia illustrativa dell'ambiente di lavoro"><div class="hero-copy"><span class="hero-kicker">CORSO · ${c.level==="intermedio"?"LIVELLO INTERMEDIO":"FONDAMENTA"}</span><h1>${esc(c.title)}</h1><p>${esc(c.desc)}</p></div></div><div class="info-strip">${kpi('12','Lezioni','book')}${kpi('4','Moduli','layers')}${kpi(c.questions.length,'Domande di allenamento','target')}</div><div class="main-aside"><div><div class="section-head"><div><h2>Programma del corso</h2><p>${c.level==="intermedio"?"Analisi tecnica, procedure verificabili e casi operativi complessi, senza ripartire dall’ABC.":"Ogni lezione include metodo, casi ed esercitazione. Progressi e note rimangono privati."}</p></div></div>${placementPanel(c.id)}${microDashboard(c.id)}${tipsEntry()}${shiftEntry()}<div class="module-list">${c.modules.map((m,i)=>{const ls=c.lessons.filter(l=>l.module===m.id),done=ls.filter(l=>saved.done.includes(l.id)).length,opened=!!state.moduleOpened[m.id];return `<section class="module-card"><button class="module-header" data-action="toggleModule" data-id="${m.id}" aria-expanded="${opened}"><span class="module-number">0${i+1}</span><span style="flex:1"><strong>${esc(m.title)}</strong><span>${done}/${ls.length} lezioni · ${esc(m.desc)}</span>${placementModuleTag(m.id)}</span>${ico('down')}</button>${opened?`<div>${ls.map((l,j)=>`<button class="lesson-row" data-action="lesson" data-id="${l.id}"><span class="lesson-index ${saved.done.includes(l.id)?'done':''}">${saved.done.includes(l.id)?ico('check',13):String(j+1).padStart(2,'0')}</span><span style="flex:1"><strong>${esc(l.title)}</strong><small>${l.minutes} minuti · ${l.id}</small></span>${ico('chev')}</button>`).join('')}<button class="lesson-row" data-action="startModule" data-id="${m.id}" ><span class="lesson-index">${ico('target',15)}</span><span style="flex:1"><strong>Verifica del modulo</strong><small>${c.questions.filter(q=>q.module===m.id).length} quesiti operativi · nessun feedback durante la prova</small></span>${ico('arrow')}</button></div>`:''}</section>`}).join('')}</div><div class="section-head"><h2>Valutazioni del corso</h2></div><div class="grid grid-2"><div class="card card-pad"><div class="pill-icon">${ico('target')}</div><h3>Skill Check ${c.level==="intermedio"?"intermedio":"diagnostico"}</h3><p>${c.skill_questions.length} casi di livello ${c.level==="intermedio"?"intermedio":"introduttivo"}: diagnosi e feedback soltanto dopo la consegna.</p>${btn('Apri Skill Check '+ico('arrow'),'testIntro','','outline')}</div><div class="card card-pad"><div class="pill-icon">${ico('book')}</div><h3>Verifica finale</h3><p>${c.final_questions.length} situazioni operative trasversali, con errori critici valutati separatamente.</p>${btn('Avvia verifica finale '+ico('arrow'),'startFinal','','outline')}</div></div><div class="alert">${c.level==='intermedio'?'Percorso intermedio didattico, non certificato. Non sostituisce attività pratica osservata, formazione obbligatoria e procedure aziendali.':'Bozza didattica in collaudo. Non sostituisce addestramento supervisionato né corsi obbligatori di sicurezza alimentare. Le procedure aziendali restano il riferimento operativo.'}</div></div><aside class="sticky-aside"><div class="card sidebar-card"><div class="card-label">IL TUO PERCORSO</div><div class="stat-circle" style="--progress:${n}%"><span>${n}%</span></div><p style="text-align:center">${completed} su 12 lezioni segnate come studiate</p>${bar(n)}<div class="divider"></div>${btn('Riprendi una lezione '+ico('arrow'),'openLast','','full')}</div></aside></div>`}
function extraLesson(){const c=currentCourse(),l=c.lessons.find(x=>x.id===state.lesson)||c.lessons[0];saved.lastLesson=l.id;save();const idx=c.lessons.indexOf(l),mod=c.modules.find(m=>m.id===l.module),tabs=[['comprendi','La lezione'],['procedura','Procedura'],['applica','Caso e pratica'],['verifica','Verifica']];return `<div class="breadcrumb"><button data-page="academy">Academy</button>${ico('chev')}<button data-page="course">${esc(c.title)}</button>${ico('chev')}<span>${l.id}</span></div><div class="lesson-layout"><div class="lesson-body"><div class="card-label">${esc(mod.title)} · ${l.id} · ${l.minutes} MIN</div><h1 class="lesson-title">${esc(l.title)}</h1><div style="display:flex;flex-wrap:wrap;gap:8px;margin-bottom:18px">${pill('STANDARD · GRATIS')}${pill(c.level==='intermedio'?'INTERMEDIO':'FONDAMENTA','neutral')}${saved.done.includes(l.id)?pill('STUDIATA'):pill('DA STUDIARE','orange')}</div><img class="lesson-hero-img" src="${l.photo}" alt="Fotografia illustrativa del contesto di lavoro"><div class="reader-toolbar"><div class="reader-tools"><span class="reader-label">Testo</span>${[['small','A−'],['medium','A'],['large','A+']].map(([k,v])=>`<button class="reader-size ${saved.readingSize===k?'chosen':''}" data-action="text${k.charAt(0).toUpperCase()+k.slice(1)}" aria-pressed="${saved.readingSize===k}">${v}</button>`).join('')}</div><div class="reader-tools"><button class="reader-tool" data-action="openPhoto">${ico('search',15)} Ingrandisci foto</button><button class="reader-tool" data-action="toggleFocus">${ico('book',15)} ${state.focusReader?'Esci da focus':'Lettura concentrata'}</button></div></div><div class="tabbar" role="tablist" aria-label="Sezioni della lezione">${tabs.map(([k,v])=>`<button class="tab" role="tab" data-action="lessonTab" data-id="${k}" aria-selected="${state.lessonTab===k}">${v}</button>`).join('')}</div>${lessonContent(l)}<section class="lesson-notes" aria-labelledby="lessonNotesTitle"><div class="lesson-notes-head"><div><div class="eyebrow">IL TUO TACCUINO</div><h2 id="lessonNotesTitle">Appunti personali</h2><p>Gli appunti restano sul dispositivo e sono inclusi nell'esportazione del backup.</p></div>${ico('edit',23)}</div><label class="sr-only" for="lessonNotes">Appunti</label><textarea id="lessonNotes" maxlength="6000" rows="4" placeholder="Che cosa voglio ricordare?">${esc((saved.notes||{})[l.id]||'')}</textarea><div class="notes-status" id="notesStatus" role="status">Salvataggio locale automatico</div></section><div class="footer-cta">${btn(ico('back')+' Precedente','previousLesson',idx===0?'disabled':'','outline')}${btn(idx===11?'Verifica finale '+ico('arrow'):'Prossima lezione '+ico('arrow'),idx===11?'startFinal':'nextLesson','','')}</div></div><aside class="sticky-aside"><div class="card sidebar-card"><div class="card-label">OBIETTIVO</div><h3>Quello che saprai spiegare</h3><p>${esc(l.objective)}</p><div class="divider"></div><div class="micro">LEZIONE ${idx+1} DI 12</div>${bar((idx+1)/12*100)}<div style="margin-top:18px">${btn(saved.done.includes(l.id)?ico('check')+' Studiata':'Segna come studiata '+ico('check'),'markComplete',`data-id="${l.id}"`,'outline full')}</div><div class="divider"></div><div class="micro">FONTI DI RIFERIMENTO</div>${c.sources.map(x=>`<p class="micro"><a href="${x.url}" target="_blank" rel="noopener noreferrer">${esc(x.label)}</a></p>`).join('')}</div><div class="alert" style="margin-top:14px">Il completamento è un'autodichiarazione; non attesta capacità pratiche e non vale come certificazione.</div></aside></div>`}
function extraSkillIntro(){const c=currentCourse();return `${header('SKILL CHECK · '+c.title.toUpperCase(),'Valuta le tue decisioni.',c.level==='intermedio'?'16 casi decisionali intermedi senza suggerimenti durante la prova.':'20 situazioni operative senza suggerimenti o feedback prima della consegna.')}${draftBanner()}<div class="main-aside"><div class="card card-pad"><h2>Prima di iniziare</h2><p>${c.level==='intermedio'?'La prova valuta la capacità di decidere in situazioni professionali complesse. Al termine suggerisce i moduli intermedi da studiare, senza attribuire qualifiche.':'La prova valuta le competenze introduttive del reparto e suggerisce un percorso mirato.'} Non costituisce certificazione.</p><fieldset class="self-assessment"><legend>Come valuti la tua preparazione attuale?</legend>${[['1','Sto iniziando'],['2','Conosco alcune basi'],['3','Lavoro con una certa autonomia'],['4','Ho esperienza avanzata']].map(([v,t])=>`<label class="self-choice"><input type="radio" name="selfAssessment" value="${v}" ${state.selfAssessment===v?'checked':''}><span>${t}</span></label>`).join('')}</fieldset><p class="micro">L'autovalutazione non influenza il punteggio. Le risposte corrette saranno visibili solo dopo la consegna.</p>${btn('Inizia lo Skill Check '+ico('arrow'),'startSkill',state.selfAssessment?'':'disabled','')}</div><aside class="card sidebar-card"><div class="pill-icon">${ico('shield')}</div><h3>Una prova, non un gioco a indovinare</h3><p>${c.skill_questions.length} scenari decisionali sui quattro moduli con alternative plausibili e nessuna indicazione delle risposte durante la prova. Non vengono mostrati aiuti né suggerimenti.</p><div class="divider"></div><p>Risposte e risultato rimangono nel browser. Non sono accessibili ai datori di lavoro.</p></aside></div>`}

function extraProgress(){
 const role=["sala","cucina","bar"].includes(state.academyRole)?state.academyRole:"sala";
 const currentHistory=LEDGER.normalize(saved.assessments,courseData);
 const ctx=microContext(),allCourses=["sala","cucina","bar","sala-intermedio","cucina-intermedio","bar-intermedio"];
 const totalActivities=allCourses.reduce((n,id)=>n+MICRO.courseMetrics(ctx,courseData(id)).completed,0);
 const due=MICRO.dueReviews(ctx).length;
 const roleNames={sala:"Sala",cucina:"Cucina",bar:"Bar"};
 const selected=Number.isInteger(state.assessmentIndex)&&state.assessmentIndex>=0&&state.assessmentIndex<currentHistory.length?currentHistory[state.assessmentIndex]:null;
 const focus=selected?LEDGER.focusAreas(selected):[];
 const latest=LEDGER.latest(currentHistory,role,courseData,'skill')||LEDGER.latest(currentHistory,role+'-intermedio',courseData,'skill');
 const courseCards=[role,role+"-intermedio"].map(id=>{
  const course=courseData(id),metrics=MICRO.courseMetrics(ctx,course);
  const last=LEDGER.latest(currentHistory,id,courseData),diagnosis=LEDGER.latest(currentHistory,id,courseData,'skill');
  return '<article class="progress-course-card"><div class="progress-course-header"><div><span class="hub-eyebrow">'+(id.includes("intermedio")?"INTERMEDIO":"FONDAMENTI")+'</span><h3>'+esc(course.title)+'</h3></div><strong>'+metrics.percent+'%</strong></div>'
  +'<div class="hub-meter" role="progressbar" aria-label="Avanzamento '+esc(course.title)+'" aria-valuemin="0" aria-valuemax="100" aria-valuenow="'+metrics.percent+'"><span style="width:'+metrics.percent+'%"></span></div>'
  +'<p>'+metrics.completed+'/60 microattività · '+metrics.completedLessons+'/12 capitoli studiati</p>'
  +'<div class="progress-module-list">'+course.modules.map(mod=>{
   const lessons=course.lessons.filter(x=>x.module===mod.id);
   const completed=lessons.reduce((n,l)=>n+MICRO.doneKeys(saved,l.id).length,0);
   const grade=diagnosis?.modules.find(g=>g.id===mod.id),warn=grade&&(grade.critical>0||grade.percent<60);
   return '<div class="progress-module-row"><div><strong>'+esc(mod.title)+'</strong><small>'+completed+'/15 attività'+(warn?' · Da ripassare':'')+'</small></div><div class="progress-mini-bar" role="progressbar" aria-label="Progresso modulo '+esc(mod.title)+'" aria-valuemin="0" aria-valuemax="100" aria-valuenow="'+Math.round(completed/15*100)+'"><span style="width:'+(completed/15*100)+'%"></span></div></div>';
  }).join('')+'</div>'
  +(last?'<p class="progress-last-test">Ultima prova: '+esc(LEDGER.displayDate(last.date))+' · '+last.percent+'%'+(last.critical?' · '+last.critical+' errori critici':'')+'</p>':'<p class="progress-last-test">Nessuna verifica conclusa in questo corso.</p>')
  +'<button type="button" class="btn outline" data-action="openCourse" data-id="'+esc(id)+'">Continua questo corso '+ico("arrow",16)+'</button></article>';
 }).join("");
 const history=currentHistory.map((a,index)=>({a,index})).reverse().slice(0,state.progressHistoryOpen?15:3);
 const historyMarkup=history.map(({a,index})=>'<div class="progress-assessment"><div class="progress-assessment-meta"><div><strong>'+esc(a.type)+'</strong><p>'+esc(LEDGER.displayDate(a.date))+' · '+(a.typeKey==="skill"?"Diagnosi orientativa":"Esercitazione valutata")+(a.accessibleMode?' · Formato alternativo':'')+'</p></div><div class="progress-assessment-score"><strong>'+a.percent+'%</strong><small>'+a.critical+' errori critici</small></div></div><button type="button" class="hub-text-link" data-action="assessmentDetails" data-id="'+index+'" aria-expanded="'+(state.assessmentIndex===index)+'"> '+(state.assessmentIndex===index?'Nascondi dettagli':'Vedi il riepilogo')+' '+ico('chev',15)+'</button></div>').join("");
 return '<div class="progress-hub studio-progress">'
  +header('DOPOTURNO STUDIO / PROGRESSI','Analisi del percorso','Tieni separati studio, verifiche e simulazioni. Qui trovi ciò che hai completato e i prossimi argomenti su cui lavorare.')
  +'<div class="progress-stats">'+[['book',saved.done.length+'/72','Capitoli studiati'],['layers',totalActivities+'/360','Microattività svolte'],['target',currentHistory.length,'Verifiche salvate'],['clock',due,'Ripassi disponibili']].map(([iconName,value,label])=>'<div class="progress-stat"><span>'+ico(iconName,21)+'</span><strong>'+value+'</strong><small>'+label+'</small></div>').join('')+'</div>'
  +'<section class="progress-section"><div class="hub-section-top"><div><span class="hub-eyebrow">PER REPARTO</span><h2>Il tuo percorso professionale</h2><p>Scegli il reparto: ogni corso mostra il progresso delle attività e gli argomenti ancora da approfondire.</p></div><div class="hub-role-tabs" role="group" aria-label="Seleziona il reparto dei progressi">'+Object.entries(roleNames).map(([id,label])=>'<button type="button" class="'+(id===role?'selected':'')+'" data-action="progressRole" data-id="'+id+'" aria-pressed="'+(id===role)+'">'+label+'</button>').join('')+'</div></div><div class="studio-evidence" aria-label="Esiti dello Skill Check del reparto selezionato"><div class="studio-evidence-top"><div><span class="studio-eyebrow">ANALISI DELLO SKILL CHECK</span><h3>Esiti teorici · '+esc(roleNames[role])+'</h3><p>Questi dati descrivono soltanto le risposte al test, non le capacità osservate sul lavoro.</p></div>'+(latest?'<span class="studio-context">'+esc(LEDGER.displayDate(latest.date))+'</span>':'')+'</div>'+(latest?.modules?.length?'<div class="studio-evidence-bars">'+latest.modules.filter(mod=>mod.total>0).map(mod=>'<div class="studio-evidence-item" data-weak="'+(mod.critical>0||mod.percent<80)+'"><div><strong>'+esc(mod.title)+'</strong><span>'+mod.correct+'/'+mod.total+' · '+mod.percent+'%</span></div><div class="progress-mini-bar" role="progressbar" aria-label="Risposte adeguate sul modulo '+esc(mod.title)+'" aria-valuemin="0" aria-valuemax="100" aria-valuenow="'+mod.percent+'"><span style="width:'+mod.percent+'%"></span></div></div>').join('')+'</div>':'<div class="studio-evidence-empty"><p>Nessun dettaglio per modulo disponibile. Fai lo Skill Check per vedere dove approfondire.</p><button type="button" class="studio-text-action" data-page="testIntro">Apri lo Skill Check '+ico('arrow',16)+'</button></div>')+'</div><div class="progress-course-grid">'+courseCards+'</div></section>'
  +'<section class="progress-section"><div class="hub-section-top"><div><span class="hub-eyebrow">PROSSIMO PASSO</span><h2>Allenati sulle priorità</h2></div></div><div class="progress-recommendation"><div>'
  +(latest?'<h3>Riparti dagli argomenti meno solidi</h3><p>Il tuo ultimo Skill Check di '+esc(roleNames[role])+' può aiutarti a scegliere il ripasso. La diagnosi non sostituisce una prova pratica.</p>':'<h3>Scopri il tuo livello di partenza</h3><p>Non hai ancora uno Skill Check per questo reparto. Puoi cominciare dalle lezioni o fare la diagnosi per avere suggerimenti mirati.</p>')
  +'</div><div><button type="button" class="btn" data-page="testIntro">Apri lo Skill Check '+ico('arrow',16)+'</button><button type="button" class="btn outline" data-action="microReviews">Ripassi'+(due?' ('+due+')':'')+'</button></div></div></section>'
  +'<section class="progress-section" aria-labelledby="progressHistoryTitle"><div class="hub-section-top"><div><span class="hub-eyebrow">REGISTRO PERSONALE</span><h2 id="progressHistoryTitle">Storico delle verifiche</h2><p>Le prove restano consultabili dopo aver chiuso la schermata. Conserviamo il riepilogo, non le risposte del test.</p></div></div>'
  +(selected?'<div class="progress-detail" role="region" aria-label="Dettagli della verifica selezionata"><div class="progress-detail-head"><div><span class="hub-eyebrow">RIEPILOGO FORMATIVO</span><h3>'+esc(selected.type)+'</h3><p>'+esc(LEDGER.displayDate(selected.date))+' · '+selected.percent+'% · '+selected.critical+' errori critici'+(selected.total?' · '+selected.correct+'/'+selected.total+' risposte corrette':'')+'</p></div><button type="button" class="btn outline small" data-action="assessmentDetails" data-id="'+state.assessmentIndex+'">Chiudi</button></div>'
   +(selected.modules.length?'<div class="progress-detail-modules">'+selected.modules.map(m=>'<div class="progress-detail-module"><div><strong>'+esc(m.title)+'</strong><small>'+m.correct+'/'+m.total+' risposte adeguate'+(m.critical?' · '+m.critical+' errori critici':'')+'</small></div><b>'+m.percent+'%</b></div>').join('')+'</div>':'<p>Per questa prova meno recente non è disponibile il riepilogo per modulo.</p>')
   +(focus.length?'<p class="progress-focus-note">Da consolidare: '+focus.map(m=>esc(m.title)).join(', ')+'.</p>':'<p class="progress-focus-note">Nessun modulo critico rilevato dai dati disponibili. Questo non dimostra competenza operativa certificata.</p>')
   +(selected.courseId?'<button type="button" class="btn" data-action="openCourse" data-id="'+esc(selected.courseId)+'">Approfondisci il corso '+ico('arrow',16)+'</button>':'')
   +'</div>':'')
  +(history.length?'<div class="progress-assessment-list">'+historyMarkup+'</div>':'<div class="progress-empty"><h3>Non hai ancora verifiche registrate</h3><p>Comincia da uno Skill Check o completa una verifica formativa. I risultati rimarranno privati sul tuo dispositivo.</p><button type="button" class="btn outline" data-page="testIntro">Vai allo Skill Check</button></div>')+(currentHistory.length>3?'<button type="button" class="studio-history-toggle" data-action="toggleHistory" aria-expanded="'+state.progressHistoryOpen+'">'+(state.progressHistoryOpen?'Mostra le ultime 3':'Mostra più verifiche')+' '+ico('down',15)+'</button>':'')
  +'</section><p class="hub-privacy">DopoTurno è ancora un prototipo. I punteggi sono risultati di prove dimostrative, non attestati professionali; i progressi sono locali e puoi esportarli dal Profilo.</p></div>';
}

function confronti(){return window.DopoTurnoForum.render({state,saved,esc,ico,header});}

function course(){const n=pct();return `<div class="breadcrumb"><button data-page="academy">Academy</button>${ico('chev')}<span>Sala e ospitalità</span>${ico('chev')}<span>Fondamenta</span></div><div class="hero-main sub-hero"><img class="hero-photo" src="assets/foto_09.jpg" alt="Sala elegante pronta per il servizio"><div class="hero-copy"><span class="hero-kicker">CORSO · STANDARD GRATUITO</span><h1>Fondamenti<br>di Sala.</h1><p>Una formazione solida per cominciare: dagli strumenti al servizio, dai clienti alle situazioni impreviste.</p></div></div><div class="info-strip">${kpi('12','Lezioni complete','book')}${kpi('4','Moduli formativi','layers')}${kpi('≈ 6h','Studio indicativo','clock')}</div><div class="main-aside"><div><div class="section-head"><div><h2>Programma del corso</h2><p>Ogni modulo sviluppa competenze precise. Inizia dove ti serve.</p></div></div>${placementPanel("sala")}${microDashboard('sala')}${tipsEntry()}${shiftEntry()}<div class="module-list">${M.map((m,i)=>{const lessons=L.filter(x=>x.module===m.id),done=lessons.filter(x=>saved.done.includes(x.id)).length;const isOpen=!!state.moduleOpened[m.id];return `<section class="module-card"><button class="module-header" data-action="toggleModule" data-id="${m.id}" aria-expanded="${isOpen}"><span class="module-number">0${i+1}</span><span style="flex:1"><strong>${esc(m.title)}</strong><span>${done}/${lessons.length} lezioni · ${esc(m.desc)}</span>${placementModuleTag(m.id)}</span>${ico('down')}</button>${isOpen?`<div>${lessons.map((x,k)=>`<button class="lesson-row" data-action="lesson" data-id="${x.id}"><span class="lesson-index ${saved.done.includes(x.id)?'done':''}">${saved.done.includes(x.id)?ico('check',13):String(k+1).padStart(2,'0')}</span><span style="flex:1"><strong>${esc(x.title)}</strong><small>${x.minutes} minuti · ${x.id}</small></span><span class="right">${ico('chev')}</span></button>`).join('')}<button class="lesson-row" data-action="startModule" data-id="${m.id}" ><span class="lesson-index">${ico('target',15)}</span><span style="flex:1"><strong>Verifica del modulo</strong><small>12 domande · valutazione dimostrativa</small></span><span class="right">${ico('arrow')}</span></button></div>`:''}</section>`}).join('')}</div><div class="section-head"><h2>Prove visive e valutazione</h2></div><div class="grid grid-2"><div class="card card-pad"><div class="pill-icon">${ico('image')}</div><h3>Laboratorio visivo</h3><p>Otto scene interattive per osservare errori e dettagli.</p><div style="margin-top:20px">${btn('Apri il laboratorio '+ico('arrow'),'visuals','','outline')}</div></div><div class="card card-pad"><div class="pill-icon">${ico('target')}</div><h3>Verifica finale</h3><p>Decisioni reali di servizio, senza aiuti durante la prova.</p><div style="margin-top:20px">${btn('Apri la prova '+ico('arrow'),'startFinal','','outline')}</div></div></div></div><aside class="sticky-aside"><div class="card sidebar-card"><div class="card-label">IL TUO PROGRESSO</div><div class="stat-circle" style="--progress:${n}%"><span>${n}%</span></div><p style="text-align:center">${L.filter(l=>saved.done.includes(l.id)).length} lezioni completate su 12</p>${bar(n)}<div class="divider"></div><div class="feature-list"><div>${ico('check')} 12 lezioni complete</div><div>${ico('check')} Quiz e casi di servizio</div><div>${ico('check')} Prove visive interattive</div><div>${ico('check')} Materiale Standard gratuito</div></div><div style="margin-top:19px">${btn('Riprendi lo studio '+ico('arrow'),'openLast','','full')}</div></div><div class="alert" style="margin-top:14px">Bozza didattica per collaudo. Non equivale a formazione obbligatoria o qualificazione professionale riconosciuta.</div></aside></div>`}
function lesson(){const l=L.find(x=>x.id===state.lesson)||L[0];saved.lastLesson=l.id;save();const index=L.findIndex(x=>x.id===l.id);const tabs=[['comprendi','La lezione'],['procedura','Procedura'],['applica','Caso e pratica'],['verifica','Verifica']];return `<div class="breadcrumb"><button data-page="academy">Academy</button>${ico('chev')}<button data-page="course">Fondamenti di Sala</button>${ico('chev')}<span>${esc(l.id)}</span></div><div class="lesson-layout"><div class="lesson-body"><div class="card-label">${esc(M.find(x=>x.id===l.module).title)} · ${l.id} · ${l.minutes} MIN</div><h1 class="lesson-title">${esc(l.title)}</h1><div style="display:flex;gap:7px;flex-wrap:wrap;margin-bottom:18px">${pill('STANDARD · GRATIS')}${pill('FONDAMENTA','neutral')}${saved.done.includes(l.id)?pill('COMPLETATA'):pill('IN APPRENDIMENTO','orange')}</div><img class="lesson-hero-img" src="${l.photo}" alt="Fotografia illustrativa dell’ambiente e del servizio di sala"><div class="reader-toolbar" aria-label="Strumenti di lettura"><div class="reader-tools"><span class="reader-label">Testo</span><button class="reader-size ${saved.readingSize==='small'?'chosen':''}" data-action="textSmall" aria-pressed="${saved.readingSize==='small'}" aria-label="Testo piccolo">A−</button><button class="reader-size ${saved.readingSize==='medium'?'chosen':''}" data-action="textMedium" aria-pressed="${saved.readingSize==='medium'}" aria-label="Testo normale">A</button><button class="reader-size ${saved.readingSize==='large'?'chosen':''}" data-action="textLarge" aria-pressed="${saved.readingSize==='large'}" aria-label="Testo grande">A+</button></div><div class="reader-tools"><button class="reader-tool" data-action="openPhoto">${ico('search',15)} Ingrandisci foto</button><button class="reader-tool" data-action="toggleFocus">${ico('book',15)} ${state.focusReader?'Esci da focus':'Lettura concentrata'}</button></div></div><div class="tabbar" role="tablist" aria-label="Sezioni della lezione">${tabs.map(([k,n])=>`<button class="tab" role="tab" data-action="lessonTab" data-id="${k}" aria-selected="${state.lessonTab===k}">${n}</button>`).join('')}</div>${lessonContent(l)}<section class="lesson-notes" aria-labelledby="lessonNotesTitle"><div class="lesson-notes-head"><div><div class="eyebrow">IL TUO TACCUINO</div><h2 id="lessonNotesTitle">Appunti personali</h2><p>Scrivi una procedura da ricordare o una domanda per il formatore. Restano su questo dispositivo.</p></div>${ico('edit',23)}</div><label class="sr-only" for="lessonNotes">Appunti per ${esc(l.title)}</label><textarea id="lessonNotes" rows="4" maxlength="6000" placeholder="Che cosa voglio ricordare di questa lezione?">${esc((saved.notes||{})[l.id]||'')}</textarea><div class="notes-status" id="notesStatus" role="status">Salvataggio locale automatico · Nessuna condivisione</div></section><div class="footer-cta">${btn(ico('back')+' Lezione precedente','previousLesson',index===0?'disabled':'','outline')}${btn(index===L.length-1?'Vai alla prova finale '+ico('arrow'):'Lezione successiva '+ico('arrow'),index===L.length-1?'startFinal':'nextLesson','','')}</div></div><aside class="sticky-aside"><div class="card sidebar-card"><div class="card-label">OBIETTIVO FORMATIVO</div><h3 style="line-height:1.4">Quello che saprai fare</h3><p>${esc(l.objective)}</p><div class="divider"></div><div class="micro">LEZIONE ${index+1} DI 12</div><div style="margin:8px 0 14px">${bar((index+1)/12*100)}</div>${btn(saved.done.includes(l.id)?ico('check')+' Segnata come completata':'Segna come completata '+ico('check'),'markComplete',`data-id="${l.id}"`,'outline full')}${btn('Esplora tutte le lezioni','course','','ghost full')}<div class="divider"></div><span class="card-label">RIFERIMENTI CODEX</span><p>${l.codex.map(x=>pill(x,'outline')).join('')}</p></div><div class="card sidebar-card" style="margin-top:16px"><div class="card-label">TRATTO DIDATTICO</div><p>Il testo è una bozza originale con taglio professionale. Le fotografie sono dimostrative e richiedono verifica tecnica prima del rilascio ufficiale.</p></div></aside></div>`}
function lessonContent(l){if(state.lessonTab==='comprendi')return `<article class="reading"><div class="eyebrow">01 / COMPRENDI</div><h2>Analisi e criterio professionale.</h2><p class="lesson-intro">${esc(l.intro)}</p>${l.sections.map((s,i)=>`<h3>${String(i+1).padStart(2,'0')}. ${esc(s.title)}</h3><p>${esc(s.text)}</p>`).join('')}<div class="callout"><strong>${ico('book',14)} &nbsp; LESSICO PROFESSIONALE</strong><p>${esc(l.glossary)}</p></div></article>`;if(state.lessonTab==='procedura')return `<article class="reading"><div class="eyebrow">02 / METODO</div><h2>Metodo e controlli del processo.</h2><p>Questa sequenza è un modello operativo: per ogni intervento considera obiettivo, verifica prevista, limiti e adattamenti ammessi dalle procedure del reparto.</p><ol>${l.steps.map(x=>`<li>${esc(x)}</li>`).join('')}</ol><div class="callout orange"><strong>${ico('alert',14)} &nbsp; ERRORI DA EVITARE</strong><ul>${l.errors.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div><h3>Varianti per ambiente</h3><p>${esc(l.environments)}</p></article>`;if(state.lessonTab==='applica')return `<article class="reading"><div class="eyebrow">03 / SUL CAMPO</div><h2>Allenati su una situazione realistica.</h2><h3>Il caso</h3><p>${esc(l.case)}</p><h3>Come comunicheresti?</h3><div class="dialogue">${esc(l.dialogue)}</div><h3>Esercitazione</h3><p>${esc(l.practice)}</p><h3>Come controllare il risultato</h3><ul>${l.criteria.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><div class="callout"><strong>COME VALUTARE LA PRATICA</strong><p>Questa attività può essere eseguita autonomamente. La spunta «completata» non costituisce verifica osservata da un professionista.</p></div></article>`;const questions=(courseData(courseForLesson(l.id))?.questions||[]).filter(q=>q.lesson===l.id);const q=questions[0];const given=state.exerciseChoice;return `<article class="reading"><div class="eyebrow">04 / ALLENAMENTO</div><h2>Valuta una decisione operativa.</h2><p>Qui stai ancora imparando: dopo la risposta riceverai una spiegazione. Lo Skill Check vero non dà aiuti durante l'esame.</p><h3>${esc(q.prompt)}</h3><div class="option-stack">${q.options.map((x,i)=>`<label class="quiz-option ${given===i?'selected':''}"><input type="radio" name="exercise-answer" value="${i}" ${given===i?'checked':''}><span>${esc(x)}</span></label>`).join('')}</div>${state.exerciseGraded?`<div class="feedback-box ${given===q.correct?'':'warn'}"><strong>${given===q.correct?'Decisione adeguata':'Da ripassare'}</strong><p style="margin:5px 0 0">${esc(q.explanation)}</p></div>`:''}<div class="footer-cta">${btn('Verifica la risposta','gradeExercise',given===null?'disabled':'','')}${btn('Prova completa del modulo '+ico('arrow'),'startModule',`data-id="${l.module}"`,'outline')}</div></article>`}
function visuals(){return `${header('LABORATORIO VISIVO','Osservare è una competenza.','Due raccolte di prove: casi professionali contestualizzati da fotografie e scene tecniche dedicate all’osservazione di anomalie.') }<div class="alert">Le fotografie mostrano l’ambiente di lavoro; la prova valuta le decisioni da prendere sulla base delle informazioni fornite. Non si chiede di indicare bicchieri o posate evidenti. Per valutare la ricerca visiva di anomalie restano scene tecniche controllate, finché non saranno disponibili fotografie con difetti reali validati.</div>${alternativeModeNote()}<div class="section-head"><h2>Scenari professionali con fotografie · 8 casi</h2><span class="chip neutral">SCELTE OPERATIVE · NON CERTIFICANTE</span></div><div class="grid grid-2">${DATA.photo_tests.map((v,i)=>`<article class="card course-card photo-test-card"><div style="height:183px;background:#172534"><img src="assets/${v.scene_file}" alt="Scena fotografica di servizio" style="width:100%;height:100%;object-fit:cover"></div><div class="course-info"><div class="card-label">FOTO ${String(i+1).padStart(2,'0')} · ${v.id}</div><h3>${esc(v.title)}</h3><p>${esc(v.prompt)}</p><button class="btn outline small" data-action="startPhoto" data-id="${v.id}">Affronta il caso ${ico('arrow',14)}</button></div></article>`).join('')}</div><div class="section-head"><h2>Controlli operativi · 8 prove</h2><span class="chip neutral">SCENE TECNICHE</span></div><div class="grid grid-2">${DATA.visual_tests.map((v,i)=>`<article class="card course-card"><div style="height:183px;background:#f6f5ee;padding:12px"><img src="assets/${v.scene}.svg" alt="Diagramma tecnico di una situazione lavorativa" style="width:100%;height:100%;object-fit:contain"></div><div class="course-info"><div class="card-label">PROVA ${String(i+1).padStart(2,'0')} · ${v.id}</div><h3>${esc(v.title)}</h3><p>${esc(v.prompt)}</p><button class="btn outline small" data-action="startVisual" data-id="${v.id}">Prova lo scenario ${ico('arrow',14)}</button></div></article>`).join('')}</div>`}
function skillIntro(){return `<div class="breadcrumb"><button data-page="academy">Academy</button>${ico('chev')}<span>Skill Check</span></div><div class="assessment-cover"><div class="left"><div class="eyebrow" style="color:#edb58c">SKILL CHECK · SALA</div><h1>Quanto conosci<br>davvero il servizio?</h1><p>Non cerchiamo risposte imparate a memoria. Vogliamo capire come ragioni davanti alle situazioni che potresti incontrare in un ristorante.</p><div class="feature-list"><div>${ico('check')} Domande operative basate sul corso</div><div>${ico('check')} Scene visive senza aiuti</div><div>${ico('check')} Risultato e spiegazioni solo alla fine</div><div>${ico('check')} Esito privato, non pubblicato sul CV</div></div><fieldset class="self-assessment"><legend>Prima di iniziare, come valuti la tua preparazione?</legend><p>La risposta è privata e non influenza il punteggio.</p>${[['1','Sto iniziando da zero'],['2','Conosco alcuni fondamentali'],['3','Lavoro con una certa autonomia'],['4','Ho esperienza avanzata']].map(([v,label])=>`<label class="self-choice"><input type="radio" name="selfAssessment" value="${v}" ${state.selfAssessment===v?'checked':''}><span>${label}</span></label>`).join('')}</fieldset>${alternativeModeNote()}${draftBanner()}${btn('Inizia Skill Check '+ico('arrow'),'startSkill',state.selfAssessment?'':'disabled','peach')}<p style="font-size:11px;margin:17px 0 0;color:#afc7b8">Dimostrazione: 16 domande + 4 scene · livello Fondamenta</p></div><div class="card sidebar-card"><div class="pill-icon">${ico('shield')}</div><h3 style="margin-top:17px">Un test serio, senza scorciatoie.</h3><p>Niente suggerimenti, niente risposta corretta durante la sessione. Le decisioni sono costruite intorno a vincoli e conseguenze operative; gli errori critici contano più di quelli marginali.</p><div class="divider"></div><div class="card-label">LIMITI DELLA PROVA</div><p>Questo Skill Check verifica i fondamentali e suggerisce un percorso personalizzato. Puoi saltare le parti già note, ma non assegna qualifiche professionali avanzate.</p></div></div><div class="section-head"><h2>Cosa succede dopo</h2></div><div class="grid grid-3">${[['target','Diagnosi','Punti di forza e aree da migliorare.'],['book','Ripasso mirato','Collegamenti ai moduli da studiare.'],['lock','Riservatezza','Il risultato rimane su questo dispositivo.']].map(([ic,t,d])=>`<div class="card card-pad"><div class="pill-icon">${ico(ic)}</div><h3>${t}</h3><p>${d}</p></div>`).join('')}</div>`}
const EXAM_DRAFT_MAX_AGE=72*60*60*1000;
const examProviders={DATA,courseData};
function draftValid(){return !!RECOVERY.sanitize(saved.examDraft,examProviders)}
function persistExam(){const e=state.exam;if(!e||e.submitted)return; saved.examDraft={...e,version:DATA.version,savedAt:Date.now()};save()}
function removeExamDraft(){saved.examDraft=null;save()}
function draftBanner(){if(!draftValid())return '';const e=saved.examDraft;return `<div class="card draft-banner" role="region" aria-label="Prova sospesa"><div><div class="card-label">PROVA SALVATA SU QUESTO DISPOSITIVO</div><h3>Hai una valutazione da riprendere</h3><p>${esc(({skill:'Skill Check',final:'Esame finale',module:'Prova di modulo',visual:'Prova visiva',photo:'Caso professionale illustrato'})[e.type]||'Valutazione')} · domanda ${e.index+1} di ${e.items.length}. La sessione scade dopo 72 ore dall’ultimo salvataggio.</p></div><div class="draft-actions"><button class="btn" data-action="resumeExam">Riprendi ${ico('arrow',15)}</button><button class="btn outline" data-action="discardExam">Elimina prova</button></div></div>`}
function restoreExam(){if(!draftValid()){toast('Nessuna prova riprendibile su questo dispositivo.');return}state.exam=RECOVERY.sanitize(saved.examDraft,examProviders);if(!state.exam){toast("Questa prova non può essere recuperata. Avvia una nuova prova.");return}if(state.exam.courseId&&ALL_COURSES[state.exam.courseId]){state.activeCourse=state.exam.courseId;state.academyRole=state.activeCourse.split("-")[0];saved.activeCourse=state.activeCourse;save()}state.visualCursor={x:450,y:260};state.visualKeyboard=false;setPage('testRun')}
function mapAssessmentItem(it,alternative=false){if(alternative&&it.type==='visual'&&it.accessible_variant)return {...it,...it.accessible_variant,type:'choice',accessibleSubstitution:true};return it}
function alternativeModeNote(){return `<div class="accessible-option"><label class="self-choice"><input id="accessibleMode" type="checkbox" ${saved.accessibleMode?'checked':''}><span>Versione alternativa testuale per prove che richiedono la visione</span></label><p class="micro">Non mostra suggerimenti. Usa scenari professionali testuali al posto delle prove su immagini. L’equivalenza di difficoltà deve ancora essere validata: nel prototipo i risultati restano distinti, senza certificazione.</p></div>`}

function buildTest(type,id){if(state.activeCourse!=='sala'){const c=currentCourse();if(draftValid()&&!confirm('Hai una prova sospesa. Iniziarne un’altra elimina la bozza. Procedere?'))return;if(type==='skill'&&!state.selfAssessment){toast('Indica prima la tua autovalutazione.');return}const items=(type==='skill'?c.skill_questions:type==='final'?c.final_questions:type==='module'?c.questions.filter(q=>q.module===id):[]).map(x=>({...x}));if(!items.length){toast('Prova non trovata.');return}state.exam={type,id,courseId:c.id,items,index:0,answers:{},started:Date.now(),submitted:false,selfAssessment:type==='skill'?state.selfAssessment:null,accessibleMode:false};persistExam();setPage('testRun');return}if(draftValid()&&!confirm('Hai una prova sospesa. Iniziarne un’altra eliminerà le risposte non consegnate. Proseguire?'))return;let items=[];if(type==='skill'){if(!state.selfAssessment){toast('Indica prima come valuti le tue conoscenze.');return}for(const m of M){const group=DATA.questions.filter(q=>q.module===m.id);for(const ix of [1,4,7,10])items.push({...group[ix]})}for(const vid of ['SAL-V01','SAL-V03','SAL-V05','SAL-V08'])items.push({...DATA.visual_tests.find(v=>v.id===vid),type:'visual'})}if(type==='final')items=DATA.final_questions.map(x=>({...x}));if(type==='module')items=DATA.questions.filter(x=>x.module===id).map(x=>({...x}));if(type==='visual')items=DATA.visual_tests.filter(x=>x.id===id).map(x=>({...x,type:'visual'}));if(type==='photo')items=DATA.photo_tests.filter(x=>x.id===id).map(x=>({...x,type:'choice'}));if(!items.length){toast('Nessuna prova disponibile');return}items=items.map(it=>mapAssessmentItem(it,!!saved.accessibleMode));state.exam={type,id,items,index:0,answers:{},started:Date.now(),submitted:false,selfAssessment:type==='skill'?state.selfAssessment:null,accessibleMode:!!saved.accessibleMode};persistExam();setPage('testRun')}
function answered(item){return Object.prototype.hasOwnProperty.call(state.exam.answers,item.id)}
function testRun(){const e=state.exam;if(!e)return skillIntro();const item=e.items[e.index];const visual=item.type==='visual';const ans=e.answers[item.id];const total=e.items.length;const cap=({skill:'SKILL CHECK',final:'PROVA FINALE',module:'VERIFICA DEL MODULO',visual:'LABORATORIO VISIVO',photo:'CASO DI SERVIZIO'})[e.type];return `<div class="exam-shell"><div class="exam-header"><div><div class="eyebrow">${cap} · ${esc(state.exam?.courseId?courseData(state.exam.courseId)?.title||'ACADEMY':'SALA')}</div><div class="micro" style="margin-top:4px" aria-live="polite">Domanda ${e.index+1} di ${total}</div></div><button class="btn outline small" data-action="pauseExam">Sospendi e salva</button></div><div class="exam-progress" role="progressbar" aria-label="Avanzamento della prova" aria-valuenow="${e.index+1}" aria-valuemin="1" aria-valuemax="${total}"><span style="width:${(e.index+1)/total*100}%"></span></div><section class="exam-card"><div class="q-id">${esc(item.id)} · ${visual?'SCENA VISIVA':item.accessibleSubstitution?'SCENARIO TESTUALE ALTERNATIVO':item.scene_file?'CASO PROFESSIONALE':'DECISIONE PROFESSIONALE'}</div>${item.scene_file&&!visual?`<div class="case-heading"><h2 tabindex="-1" id="examQuestionTitle">${esc(item.title)}</h2><p>${esc(item.prompt)}</p></div>`:`<h2 tabindex="-1" id="examQuestionTitle">${esc(item.prompt)}</h2>`}${item.scene_file&&!visual?`<figure class="case-photo"><img src="assets/${esc(item.scene_file)}" alt="Fotografia dell’ambiente di servizio collegata al caso"><figcaption>Scenario di servizio. La fotografia mostra il contesto, non suggerisce la risposta.</figcaption></figure>`:''}${visual?`<div class="visual-board" id="visualBoard" data-action="visualPoint" role="button" tabindex="0" aria-describedby="boardInstructions" aria-label="Scena interattiva. Usa il tocco o le frecce e Invio per scegliere i punti."><img src="assets/${item.scene_file||item.scene+'.svg'}" alt="${item.scene_file?'Fotografia di attività in sala da esaminare; nessuna soluzione è segnalata':'Schema di lavoro da esaminare senza indicazioni delle soluzioni'}">${(ans||[]).map((pt,i)=>`<span class="visual-dot" style="left:${(pt.x/900)*100}%;top:${(pt.y/520)*100}%">${i+1}</span>`).join('')}${state.visualKeyboard?`<span class="visual-cursor" style="left:${(state.visualCursor.x/900)*100}%;top:${(state.visualCursor.y/520)*100}%" aria-hidden="true"></span>`:''}</div><div class="exam-tools"><span class="selection-counter" aria-live="polite">Punti selezionati: ${(ans||[]).length}</span><button class="btn small outline" data-action="toggleVisualKeyboard" aria-pressed="${state.visualKeyboard}">${ico('target',14)} ${state.visualKeyboard?'Nascondi cursore':'Usa la tastiera'}</button><button class="btn small outline" data-action="undoPoint" ${!(ans||[]).length?'disabled':''}>Annulla l’ultimo punto</button></div><p class="exam-note" id="boardInstructions">Il numero di elementi non è anticipato. Tocca un punto nell’immagine; da tastiera usa le frecce e premi Invio. Le selezioni non segnalano se hai risposto correttamente. Se non puoi utilizzare la modalità visiva, torna alla schermata iniziale e seleziona il percorso testuale.</p>`:`<div class="option-stack" role="radiogroup" aria-label="Risposte possibili">${item.options.map((text,i)=>`<label class="quiz-option ${ans===i?'selected':''}"><input type="radio" name="examAnswer" value="${i}" ${ans===i?'checked':''}><span>${esc(text)}</span></label>`).join('')}</div>`}<div class="divider" style="margin-top:24px"></div><div class="footer-cta"><button class="btn outline" data-action="previousQuestion" ${e.index===0?'disabled':''}>${ico('back')} Indietro</button><span class="exam-note">Nessun feedback durante la prova</span><button class="btn" data-action="nextQuestion" ${!answered(item)?'disabled':''}>${e.index===total-1?'Consegna la prova':`Continua ${ico('arrow')}`}</button></div></section><div class="micro" style="padding:15px 4px">Bozza salvata automaticamente nel browser di questo dispositivo; non sincronizzata e non protetta come un esame ufficiale. La prova reale richiederà correzione e sessioni lato server.</div></div>`}
function gradeItem(it,ans){if(it.type!=='visual')return {ok:ans===it.correct,hits:ans===it.correct?1:0,expected:1,wrong:ans===it.correct?0:1,txt:it.explanation};let hits=0,used=[];for(const [x,y] of it.spots){const j=(ans||[]).findIndex((pt,i)=>!used.includes(i)&&Math.hypot(x-pt.x,y-pt.y)<=59);if(j>=0){used.push(j);hits++}}let wrong=(ans||[]).length-hits;return {ok:hits===it.spots.length&&wrong===0,hits,wrong,expected:it.spots.length,txt:`Zone rilevanti: ${it.spot_names.join('; ')}. Individuate ${hits} su ${it.spots.length}; selezioni non pertinenti ${wrong}.`}}
function computeResult(e){let grades=e.items.map(it=>({item:it,...gradeItem(it,e.answers[it.id])}));let correct=grades.filter(x=>x.ok).length;let errors=grades.filter(x=>x.item.critical&&!x.ok).length;let percent=Math.round(correct/grades.length*100);return {grades,correct,errors,percent,passed:percent>=80&&!errors}}
function testResults(){const e=state.exam;if(!e||!e.submitted)return skillIntro();const r=computeResult(e);return `<div class="exam-shell"><div class="breadcrumb"><button data-page="academy">Academy</button>${ico('chev')}<span>Risultato della prova</span></div><div class="results-hero"><div class="eyebrow" style="color:#efb58d">LA TUA VALUTAZIONE · ${e.type==='skill'?'DIAGNOSTICA':'FORMATIVA'}</div><h1>Non un voto.<br>Un punto di partenza.</h1><div style="display:flex;align-items:end;gap:23px;margin-top:21px"><div class="results-number">${r.percent}%</div><p style="margin:0 0 7px;font-size:12px">${r.correct} / ${e.items.length} prove completamente corrette<br>${r.errors} errori critici</p></div></div><div class="card card-pad" style="margin-top:18px"><div class="pill-icon">${ico(r.passed?'circlecheck':'target')}</div><h3>${e.type==='skill'?'Profilo diagnostico · '+(courseData(e.courseId||'sala')?.level==='intermedio'?'Intermedio':'Fondamenta'):r.passed?'Soglia dimostrativa raggiunta':'Conoscenze da consolidare'}</h3><p>${e.type==='skill'?'Questo Skill Check suggerisce i moduli da approfondire in base alle decisioni prese nella prova, senza obbligarti a ripetere i contenuti già noti. Non attribuisce qualifiche professionali o competenze pratiche certificate. Autovalutazione iniziale: '+({'1':'Parto da zero','2':'Conosco le basi','3':'Ho una certa autonomia','4':'Ho esperienza avanzata'}[e.selfAssessment]||'non dichiarata')+'. Il confronto non equivale a una certificazione professionale.':r.passed?'Hai superato la soglia proposta per questo prototipo. Non equivale a una prova pratica osservata.':'Rivedi i punti critici e riprova con maggiore preparazione. La valutazione non penalizza il tuo profilo pubblico.'}</p><div class="footer-cta">${btn('Esplora il programma '+ico('arrow'),'course','','')}<button class="btn outline" data-action="toggleReview">${state.viewReview?'Nascondi':'Mostra'} la correzione</button></div></div>${e.type==="skill"?placementPanel(e.courseId||"sala"):""}${state.viewReview?`<div class="card card-pad" style="margin-top:18px"><h3>Spiegazioni, ora disponibili</h3><p>Durante il test non sono state mostrate. Le soluzioni seguenti riguardano soltanto la prova appena conclusa.</p>${r.grades.map((g,i)=>`<div class="review-item"><div style="display:flex;align-items:center;justify-content:space-between"><span class="card-label">${g.item.id} · ${i+1}/${r.grades.length}</span>${pill(g.ok?'Adeguata':'Da rivedere',g.ok?'':'orange')}</div><h4>${esc(g.item.prompt)}</h4><p>${esc(g.txt)}</p>${g.item.type==='visual'?`<p>Elementi della scena: ${esc(g.item.spot_names.join(', '))}.</p>`:`<p><strong>Risposta corretta:</strong> ${esc(g.item.options[g.item.correct])}</p>`}</div>`).join('')}</div>`:''}<div class="alert" style="margin-top:19px">${e.accessibleMode?'È stato utilizzato il percorso testuale alternativo: l’equivalenza con le prove visive non è ancora stata validata. ':''}Il risultato è soltanto dimostrativo. Prima di un impiego certificante servono prove sul campo, un protocollo di validazione e controllo delle chiavi lato server.</div></div>`}
function progress(){return `${header('IL TUO PROFILO FORMATIVO','Le competenze, con chiarezza.','I progressi sono privati e distinti dalle esperienze di lavoro realmente svolte.')}<div class="info-strip">${kpi(saved.done.length,'Lezioni studiate','book')}${kpi(saved.assessments.length,'Prove svolte','target')}${kpi(pct()+'%','Corso Sala','medal')}</div><div class="main-aside" style="margin-top:22px"><div><div class="card card-pad"><div class="section-head" style="margin-top:0"><h2>Progressione per modulo</h2></div>${M.map((m,i)=>{const group=L.filter(x=>x.module===m.id);let count=group.filter(x=>saved.done.includes(x.id)).length;return `<div style="margin-bottom:20px"><div style="display:flex;align-items:center;justify-content:space-between"><strong style="font-size:13px">0${i+1} · ${esc(m.title)}</strong><span class="micro">${count}/${group.length}</span></div><div style="margin-top:9px">${bar(count/group.length*100)}</div></div>`}).join('')}${btn('Torna al programma '+ico('arrow'),'course','','outline')}</div><div class="section-head"><h2>Le tue valutazioni</h2></div>${saved.assessments.length?`<div class="card card-pad">${saved.assessments.slice(-6).reverse().map(a=>`<div class="toggle-row"><div><strong style="font-size:13px">${esc(a.type)}</strong><div class="micro">${new Date(a.date).toLocaleDateString('it-IT')} · Test dimostrativo</div></div><strong>${a.percent}%</strong></div>`).join('')}</div>`:`<div class="card card-pad"><p>Nessuna valutazione ancora completata. Puoi iniziare dallo Skill Check o dalle lezioni.</p>${btn('Apri lo Skill Check','testIntro','','outline')}</div>`}</div><aside><div class="card sidebar-card"><div class="pill-icon">${ico('file')}</div><h3 style="margin-top:14px">Collegamento con Carriera</h3><p>Nel prodotto definitivo potrai scegliere quali risultati formativi aggiungere al CV. Il prototipo non pubblica nulla online.</p>${btn('Anteprima CV '+ico('arrow'),'career','','outline full')}</div><div class="alert" style="margin-top:15px">La lezione completata è un'autodichiarazione di studio, non una competenza pratica attestata.</div></aside></div>`}
function codex(){const rows=[['C00.01','Preparazione al turno','Controllare obiettivi, risorse e informazioni utili prima del servizio.'],['C00.02','Igiene e prevenzione','Garantire condizioni igieniche e verificare gli strumenti di lavoro.'],['C00.03','Postazione e organizzazione','Predisporre i materiali necessari e ridurre gli imprevisti.'],['C00.04','Comunicazione operativa','Trasmettere informazioni corrette alla persona responsabile.'],['C01.01','Ruoli in sala','Distinguere funzioni, ranghi e responsabilità operative.'],['C01.02','Mise en place','Preparare un coperto coerente con lo stile e le esigenze del servizio.']];return `${header('DOPOTURNO CODEX','Conoscere il perché.','Una struttura consultabile di norme, procedure e buone pratiche. Le schede illustrate sono bozze editoriali, non standard approvati.')}<div class="hero-main sub-hero"><img class="hero-photo" src="assets/foto_04.jpg" alt="Professionista che consulta istruzioni operative"><div class="hero-copy"><span class="hero-kicker">LA BASE DELLA FORMAZIONE</span><h1>Il sapere,<br>senza improvvisazioni.</h1><p>Ogni lezione indica le competenze, le procedure e i riferimenti pertinenti.</p></div></div><div class="section-head"><h2>Schede collegate a Sala</h2></div><div class="grid grid-2">${rows.map(r=>`<div class="card card-pad"><div class="card-label">${esc(r[0])} · BOZZA</div><h3>${esc(r[1])}</h3><p>${esc(r[2])}</p></div>`).join('')}</div><div class="card card-pad" style="margin-top:18px"><h3>Riferimenti ufficiali</h3><p>Per le informazioni di sicurezza e normativa, la versione pubblicata dovrà verificare le fonti applicabili e la loro attualità.</p><div class="resource-links" style="margin-top:14px">${DATA.sources.map(x=>`<a href="${esc(x.url)}" target="_blank" rel="noopener noreferrer">${ico('external',13)} ${esc(x.title)}</a>`).join('')}</div></div>`}
const DEMO_POSTS=[
{id:'demo-briefing',name:'Sofia · Sala',role:'Cameriera · profilo dimostrativo',title:'Quando il briefing cambia il servizio',body:'Una prenotazione comunica all’ultimo momento un’allergia alimentare. Nel tuo locale chi raccoglie l’informazione e come arriva correttamente a cucina e sala?',category:'domanda',demo:true},
{id:'demo-banco',name:'Marco · Bar',role:'Bartender · profilo dimostrativo',title:'Organizzare il banco sotto pressione',body:'Durante il pienone, due comande arrivano insieme e un collega ha bisogno della macchina espresso. Come gestiresti priorità, spazio e comunicazione?',category:'confronto',demo:true}];
const COMMUNITY_TYPES={racconto:'Racconto',domanda:'Domanda',confronto:'Confronto',consiglio:'Consiglio'};
const niceDate=s=>{try{return new Intl.DateTimeFormat('it-IT',{day:'numeric',month:'short',year:'numeric'}).format(new Date(s))}catch{return 'Oggi'}};
function allCommunityPosts(){const legacy=Array.isArray(saved.draftPosts)?saved.draftPosts.map((body,i)=>({id:'legacy-'+i,name:'Tu',role:'Membro · locale',title:'Dal tuo turno',body,category:'racconto',createdAt:'2026-11-02',owned:true})):[];const own=[...saved.communityPosts].reverse().map(p=>({...p,name:'Tu',role:'Post privato sul dispositivo',owned:true}));return [...own,...legacy,...DEMO_POSTS].filter(p=>!saved.hiddenDemoPosts.includes(p.id))}
function communityPage(){const all=allCommunityPosts();const q=state.feedSearch.trim().toLocaleLowerCase('it');const filtered=all.filter(p=>(state.feedFilter==='all'||(state.feedFilter==='bookmarks'?saved.bookmarkedPosts.includes(p.id):p.category===state.feedFilter))&&(!q||[p.title,p.body,p.name,p.category].join(' ').toLocaleLowerCase('it').includes(q)));return `${header('LA COMMUNITY','La ristorazione, vista da chi la vive.','Esperienze e problemi reali del mestiere, raccontati con rispetto.',btn(ico('plus')+' Scrivi un post','newPost','',''))}${featureHero('home')}<div class="card card-pad" style="margin-top:18px"><div class="card-label">STORIE DEL TURNO</div><h3>Una situazione difficile? Parliamone insieme.</h3><p>Racconti anonimi tra camerieri, cuochi e baristi, con commenti, risposte e punti di vista diversi.</p>${btn('Apri Confronti '+ico('arrow'),'confronti','','outline')}</div><div class="card community-disclaimer" role="note"><span class="pill-icon">${ico('shield')}</span><div><strong>Anteprima privata della Community</strong><p>Quello che scrivi rimane soltanto in questo browser. I due post iniziali sono esempi, non persone o conversazioni reali. Non esistono ancora messaggi o notifiche condivisi.</p></div></div><div class="main-aside" style="margin-top:22px"><section class="feed-section"><div class="section-head"><h2>Conversazioni</h2><span class="micro">${filtered.length} ${filtered.length===1?'contenuto':'contenuti'} visibili</span></div><label for="communitySearch" class="sr-only">Cerca nelle conversazioni</label><input class="search-input" id="communitySearch" value="${esc(state.feedSearch)}" placeholder="Cerca argomenti o parole chiave" autocomplete="off"><div class="community-filters" role="group" aria-label="Filtra la Community">${[['all','Tutti'],...Object.entries(COMMUNITY_TYPES),['bookmarks','Salvati']].map(([key,label])=>`<button class="feed-filter ${state.feedFilter===key?'active':''}" data-action="feedFilter" data-id="${key}" aria-pressed="${state.feedFilter===key}">${esc(label)}</button>`).join('')}</div>${filtered.length?filtered.map((p,i)=>`<article class="card social-post" id="post-${esc(p.id)}"><div class="social-head"><span class="avatar ${p.owned?'orange':''}">${p.owned?'TU':p.id==='demo-briefing'?'SF':'MB'}</span><div style="flex:1"><strong>${esc(p.name)}</strong><small style="display:block">${esc(p.role)}${p.createdAt?' · '+esc(niceDate(p.createdAt)):''}</small></div>${pill(p.demo?'ESEMPIO':COMMUNITY_TYPES[p.category]||'Racconto',p.demo?'neutral':'')}</div><div class="community-topic">${esc(COMMUNITY_TYPES[p.category]||'Racconto')}</div><h3>${esc(p.title)}</h3><p class="post-body">${esc(p.body)}</p><div class="social-actions"><button data-action="likePost" data-id="${esc(p.id)}" aria-pressed="${saved.favoritePosts.includes(p.id)}">${ico('heart')} ${saved.favoritePosts.includes(p.id)?'Ti piace':'Mi piace'}</button><button data-action="comments" data-id="${esc(p.id)}" aria-expanded="${state.expandedPost===p.id}">${ico('message')} Commenti (${(saved.communityComments[p.id]||[]).length})</button><button data-action="bookmarkPost" data-id="${esc(p.id)}" aria-pressed="${saved.bookmarkedPosts.includes(p.id)}">${ico('book')} ${saved.bookmarkedPosts.includes(p.id)?'Salvato':'Salva'}</button>${p.owned?`<button data-action="editPost" data-id="${esc(p.id)}">${ico('file')} Modifica</button><button data-action="deletePost" data-id="${esc(p.id)}">Elimina</button>`:`<button data-action="hideDemoPost" data-id="${esc(p.id)}">Nascondi esempio</button>`}</div>${state.expandedPost===p.id?`<section class="comment-box" aria-label="Commenti al post"><h4>Discussione locale</h4>${(saved.communityComments[p.id]||[]).map(c=>`<div class="comment"><div><strong>Tu</strong><span class="micro"> · ${esc(niceDate(c.createdAt))}</span></div><p>${esc(c.body)}</p><button class="text-link" data-action="deleteComment" data-id="${esc(p.id)}" data-comment-id="${esc(c.id)}">Elimina commento</button></div>`).join('')||'<p class="micro">Nessun commento. Scrivi il primo nella tua prova privata.</p>'}<label for="commentInput-${esc(p.id)}" class="sr-only">Scrivi un commento</label><textarea id="commentInput-${esc(p.id)}" class="comment-input" rows="3" maxlength="600" placeholder="Aggiungi un commento pertinente…"></textarea><button class="btn small" data-action="addComment" data-id="${esc(p.id)}">Aggiungi commento</button></section>`:''}</article>`).join(''):`<div class="card card-pad empty"><h3>Nessuna conversazione trovata.</h3><p>Modifica i filtri oppure avvia tu un argomento.</p>${btn('Scrivi un post','newPost','','outline')}</div>`}</section><aside><div class="card sidebar-card"><div class="pill-icon">${ico('academy')}</div><h3 style="margin-top:14px">Impara qualcosa oggi.</h3><p>Le lezioni di Sala sono disponibili nel percorso Standard gratuito.</p>${btn('Apri la Academy '+ico('arrow'),'academy','','full')}</div><div class="card sidebar-card" style="margin-top:16px"><div class="pill-icon">${ico('career')}</div><h3 style="margin-top:14px">Costruisci il tuo percorso.</h3><p>Il tuo CV distingue le competenze dichiarate da quelle verificate.</p>${btn('Scopri Carriera','career','','outline full')}</div></aside></div>`}
function discover(){const q=state.filter.trim().toLowerCase();const targets=[{title:'Fondamenti di Sala',kind:'Corso',desc:'12 lezioni · Standard',act:'course',img:photo('03')},{title:'Skill Check Sala',kind:'Valutazione',desc:'20 prove dimostrative',act:'testIntro',img:photo('04')},{title:'Codex del servizio',kind:'Biblioteca',desc:'Buone pratiche e riferimenti',act:'codex',img:photo('06')},{title:'Laboratorio visivo',kind:'Esercitazioni',desc:'8 scene interattive',act:'visuals',img:photo('02')},{title:'Fondamenti di cucina',kind:'Corso',desc:'12 lezioni · 4 moduli',act:'openCourse',id:'cucina',img:photo('01')},{title:'Fondamenti di bar',kind:'Corso',desc:'12 lezioni · 4 moduli',act:'openCourse',id:'bar',img:photo('05')},{title:'Sala intermedia',kind:'Corso intermedio',desc:'12 lezioni · Regia del servizio',act:'openCourse',id:'sala-intermedio',img:photo('09')},{title:'Cucina intermedia',kind:'Corso intermedio',desc:'12 lezioni · Produzione e controllo',act:'openCourse',id:'cucina-intermedio',img:photo('07')},{title:'Bar intermedio',kind:'Corso intermedio',desc:'12 lezioni · Tecnica e gestione del banco',act:'openCourse',id:'bar-intermedio',img:photo('05')},{title:'Confronti tra colleghi',kind:'Community',desc:'Episodi anonimi, commenti e consigli',act:'confronti',img:photo('06')}];const results=targets.filter(x=>(x.title+' '+x.kind+' '+x.desc).toLowerCase().includes(q));return `${header('SCOPRI DOPOTURNO','Trova ciò che ti serve.','Corsi, competenze e strumenti pensati per chi lavora nella ristorazione.')}<div class="card card-pad"><div class="card-label">CERCA NELL'ANTEPRIMA</div><input class="search-input" id="discoverInput" placeholder="Cerca corsi, valutazioni, argomenti…" value="${esc(state.filter)}" autocomplete="off" style="margin-top:10px"><div class="micro" style="margin-top:8px">La ricerca riguarda soltanto i contenuti disponibili in questo prototipo.</div></div><div class="section-head"><h2>Esplora i contenuti</h2><span class="micro">${results.length} risultati</span></div><div class="grid grid-3">${results.map(r=>`<article class="card course-card ${!r.act?'inactive':''}" ${r.act?(r.id?`data-action="${r.act}" data-id="${r.id}"`:`data-page="${r.act}"`):''}><img class="course-photo" src="${r.img}" alt="${esc(r.title)}"><div class="course-info"><span class="card-label">${esc(r.kind)}</span><h3>${esc(r.title)}</h3><p>${esc(r.desc)}</p><div class="course-foot"><span>${r.act?'Apri':'Non ancora disponibile'}</span><span class="arrow-circle">${ico(r.act?'arrow':'lock')}</span></div></div></article>`).join('')}</div>${results.length?'':`<div class="empty">Non abbiamo trovato risultati nell'anteprima. Prova un'altra ricerca.</div>`}`}
function career(){const people=[{n:'Giulia M.',job:'Cameriera',city:'Verona',skills:'Accoglienza, servizio di sala',initials:'GM'},{n:'Luca R.',job:'Aiuto cuoco',city:'Brescia',skills:'Preparazioni di base, organizzazione',initials:'LR'},{n:'Sofia L.',job:'Bartender',city:'Milano',skills:'Caffetteria, beverage',initials:'SL'}];const jobs=[{title:'Cameriere/a di sala',company:'Trattoria del Borgo · esempio',location:'Verona',type:'Tempo determinato',pay:'Retribuzione non indicata',skills:'Servizio · Accoglienza'},{title:'Aiuto cuoco',company:'Bistrot Verde · esempio',location:'Brescia',type:'Apprendistato',pay:'Retribuzione non indicata',skills:'Preparazioni · Mise en place'},{title:'Barista',company:'Caffè Centrale · esempio',location:'Vicenza',type:'Part-time',pay:'Retribuzione non indicata',skills:'Caffetteria · Banco'}];const filtered=people.filter(x=>(x.n+' '+x.job+' '+x.city+' '+x.skills).toLowerCase().includes(state.careerFilter.toLowerCase()));const careerTabs=[['people','Professionisti'],['jobs','Offerte'],['cv','Il mio CV']];return `${header('LA TUA IDENTITÀ PROFESSIONALE','Le competenze hanno un futuro.','Profili, curriculum e opportunità nel settore: qui tutto è una simulazione locale.')}${featureHero('career')}<div class="career-tabbar" role="tablist" aria-label="Sezioni Carriera">${careerTabs.map(([k,label])=>`<button role="tab" aria-selected="${state.careerTab===k}" class="career-tab ${state.careerTab===k?'active':''}" data-action="careerTab" data-id="${k}">${label}</button>`).join('')}</div>${state.careerTab==='people'?`<div class="main-aside"><section><div class="section-head"><h2>Esplora professionisti</h2>${pill('PERSONE FITTIZIE','neutral')}</div><label for="careerInput" class="sr-only">Cerca professionisti</label><input class="search-input" id="careerInput" value="${esc(state.careerFilter)}" placeholder="Cerca professione, città o competenze"><div class="people" style="margin-top:14px">${filtered.map((x,i)=>`<div class="person"><span class="avatar ${i===1?'orange':''}">${x.initials}</span><div style="flex:1"><strong>${x.n}</strong><small>${x.job} · ${x.city}</small><small>${x.skills}</small></div>${pill('ESEMPIO','neutral')}</div>`).join('')}${filtered.length?'':`<div class="empty">Nessun profilo fittizio corrisponde alla ricerca.</div>`}</div><div class="alert" style="margin-top:16px">In produzione ogni profilo apparirà qui soltanto dopo una scelta esplicita di visibilità. La consultazione della directory non autorizza automaticamente l’accesso al CV completo.</div></section><aside class="card sidebar-card"><div class="pill-icon">${ico('file')}</div><h3>Costruisci il tuo CV</h3><p>Raccogli formazione, competenze e informazioni che scegli di condividere.</p>${btn('Apri il mio CV '+ico('arrow'),'careerTab',`data-id="cv"`,'outline full')}</aside></div>`:state.careerTab==='jobs'?`<div class="main-aside"><section><div class="section-head"><h2>Opportunità professionali</h2>${pill('ANNUNCI DIMOSTRATIVI','neutral')}</div>${jobs.map(j=>`<article class="card job-card"><div class="card-label">ESEMPIO FITTIZIO · NESSUNA CANDIDATURA REALE</div><h3>${esc(j.title)}</h3><p>${esc(j.company)} · ${esc(j.location)}</p><div class="job-meta"><span>${esc(j.type)}</span><span>${esc(j.pay)}</span><span>${esc(j.skills)}</span></div><button class="btn outline small" data-action="mockApplication">Visualizza requisiti demo</button></article>`).join('')}</section><aside class="card sidebar-card"><div class="pill-icon">${ico('shield')}</div><h3>Annunci trasparenti</h3><p>Nel prodotto reale saranno richiesti dati su mansione, luogo, orario, contratto e condizioni economiche conformemente agli obblighi applicabili.</p></aside></div>`:`<div class="main-aside"><section class="card card-pad"><div class="section-head"><div><div class="eyebrow">EDITOR DEL CURRICULUM</div><h2>Il tuo profilo professionale</h2></div>${pill('PRIVATO · DEMO','neutral')}</div><p>Compila solo ciò che vuoi includere. I dati sono salvati esclusivamente sul browser e non sono pubblicati online.</p><div class="cv-editor-grid"><label>Nome da mostrare<input class="search-input" data-cv="cvName" value="${esc(saved.cvName)}" placeholder="Nome e cognome"></label><label>Ruolo desiderato<input class="search-input" data-cv="cvTitle" value="${esc(saved.cvTitle)}" placeholder="Es. Cameriere junior"></label><label>Area professionale<input class="search-input" data-cv="cvLocation" value="${esc(saved.cvLocation)}" placeholder="Es. Verona e provincia"></label><label>Competenze dichiarate<input class="search-input" data-cv="cvSkills" value="${esc(saved.cvSkills)}" placeholder="Es. Accoglienza, servizio"></label></div><label class="cv-label">Presentazione professionale<textarea data-cv="cvSummary" rows="4" placeholder="Descrivi esperienza, obiettivi e disponibilità senza inserire dati sensibili.">${esc(saved.cvSummary)}</textarea></label><div class="toggle-row"><label for="cv-results">Includi le verifiche formative non diagnostiche nell’anteprima CV</label><input id="cv-results" type="checkbox" class="toggle" ${saved.cvResults?'checked':''}></div><div class="toggle-row"><label for="cv-public">Simula la presenza nella directory (non pubblica davvero)</label><input id="cv-public" type="checkbox" class="toggle" ${saved.cvPublished?'checked':''}></div><div class="career-note">I risultati del solo Skill Check non diventano credenziali pubbliche. Il prototipo non permette di inviare o condividere questo CV.</div><div class="cv-print card" aria-label="Anteprima curriculum"><div class="cv-kicker">DOPOTURNO · CV PERSONALE</div><h2>${esc(saved.cvName||'Il tuo nome')}</h2><p class="cv-role">${esc(saved.cvTitle||'Professione desiderata')} · ${esc(saved.cvLocation||'Zona di lavoro')}</p><div class="divider"></div><h3>Presentazione</h3><p>${esc(saved.cvSummary||'Scrivi una presentazione professionale per completare la tua anteprima.')}</p><h3>Competenze dichiarate</h3><p>${esc(saved.cvSkills||'Aggiungi le tue competenze.')}</p><h3>Formazione DopoTurno</h3><p>Lezioni studiate: ${saved.done.filter(id=>allCourseLessons().some(l=>l.id===id)).length} su 72.</p>${saved.cvResults?`<p>Prove formative demo concluse: ${saved.assessments.filter(x=>!x.type.startsWith('Skill Check')).length}. Nessuna qualifica ufficiale attestata.</p>`:''}<p class="micro">Documento dimostrativo non verificato; esperienze e capacità pratiche non sono certificate.</p></div><div class="footer-cta"><button class="btn outline" data-action="printCV">Stampa / Salva PDF</button>${btn('Continua l’Academy '+ico('arrow'),'academy','','')}</div></section><aside class="card sidebar-card"><div class="pill-icon">${ico('shield')}</div><h3>I tuoi dati, sotto controllo</h3><p>La visibilità simulata non rende pubblico nulla. Per l’app reale serviranno autorizzazioni verificabili, scadenze e registro degli accessi.</p><div class="divider"></div><p class="micro">Stato locale: ${saved.cvPublished?'visibilità simulata attiva':'privato'}.</p></aside></div>`}`}


